import 'package:flutter/material.dart';

/// Merkezi yerelleştirme. Desteklenen diller: TR, EN, DE, FR, ES, AR, RU, AZ, NL, PT.
class AppLocalizations {
  AppLocalizations(this.locale);

  final Locale locale;

  static const List<Locale> supportedLocales = [
    Locale('tr'),
    Locale('en'),
    Locale('de'),
    Locale('fr'),
    Locale('es'),
    Locale('ar'),
    Locale('ru'),
    Locale('az'),
    Locale('nl'),
    Locale('pt'),
  ];

  /// Her dil kodu için Ayarlar’da gösterilecek etiket anahtarı (örn. de → language_german).
  static const Map<String, String> languageCodeToLabelKey = {
    'tr': 'language_turkish',
    'en': 'language_english',
    'de': 'language_german',
    'fr': 'language_french',
    'es': 'language_spanish',
    'ar': 'language_arabic',
    'ru': 'language_russian',
    'az': 'language_azerbaijani',
    'nl': 'language_dutch',
    'pt': 'language_portuguese',
  };

  static AppLocalizations of(BuildContext context) {
    final l10n = Localizations.of<AppLocalizations>(context, AppLocalizations);
    return l10n ?? AppLocalizations(const Locale('tr'));
  }

  String t(String key) {
    return _values[locale.languageCode]?[key] ?? _values['en']?[key] ?? key;
  }

  /// Placeholder destekli: {0}, {1} ile değiştir.
  String tArgs(String key, List<String> args) {
    String s = t(key);
    for (var i = 0; i < args.length; i++) {
      s = s.replaceAll('{$i}', args[i]);
    }
    return s;
  }

